mapper.select:
SELECT NO, EMAIL, NICKNAME, PROFILE, CREATED_AT, STATUS
FROM USERS
WHERE NO = #{memberId}

mapper.update:
UPDATE USERS
SET EMAIL = #{email},
    NICKNAME = #{nickname},
    PROFILE = #{profile},
    STATUS = #{status}
WHERE NO = #{id}

mapper.select:
SELECT COUNT(*)
FROM USERS
WHERE NICKNAME = #{nickname}
  AND NO != #{memberId}

mapper.update:
UPDATE USERS
SET NICKNAME = #{nickname}
WHERE NO = #{memberId}
  AND STATUS = 'Y'

UPDATE USERS
SET PROFILE = #{profile}
WHERE NO = #{memberId}
  AND STATUS = 'Y'

UPDATE USERS
SET STATUS = #{status}
WHERE NO = #{memberId}
  AND STATUS = 'Y'

mapper.select:
SELECT PT.THEMA
FROM PLANNER_THEMA PT
JOIN PLANNER P ON PT.PLANNER_ID = P.ID
WHERE P.ID = #{plannerId}
  AND P.USER_ID = #{memberId}
ORDER BY PT.THEMA ASC

mapper.update:
UPDATE PLANNER
SET STATUS = 'N'
WHERE ID = #{plannerId}
  AND USER_ID = #{memberId}
  AND STATUS = 'Y'

mapper.delete:
DELETE PP
FROM PLACE_PLAN PP
JOIN DAY_PLAN DP ON PP.DAY_ID = DP.ID
JOIN PLANNER P ON DP.PLANNER_ID = P.ID
WHERE P.ID = #{plannerId}
  AND P.USER_ID = #{memberId}

DELETE DP
FROM DAY_PLAN DP
JOIN PLANNER P ON DP.PLANNER_ID = P.ID
WHERE P.ID = #{plannerId}
  AND P.USER_ID = #{memberId}

DELETE PR
FROM PLANNER_REGIONS PR
JOIN PLANNER P ON PR.PLANNER_ID = P.ID
WHERE P.ID = #{plannerId}
  AND P.USER_ID = #{memberId}

DELETE PT
FROM PLANNER_THEMA PT
JOIN PLANNER P ON PT.PLANNER_ID = P.ID
WHERE P.ID = #{plannerId}
  AND P.USER_ID = #{memberId}

